{
  "name": "@prismer/opencode-plugin",
  "version": "1.9.0",
  "description": "Evolution-aware plugin for OpenCode — connects task execution to the Prismer Evolution Network for cross-agent learning",
  "keywords": [
    "prismer",
    "opencode",
    "evolution",
    "ai-agent",
    "cross-agent-learning",
    "opencode-plugin"
  ],
  "license": "MIT",
  "author": "Prismer <dev@prismer.cloud>",
  "repository": {
    "type": "git",
    "url": "https://github.com/Prismer-AI/PrismerCloud.git",
    "directory": "sdk/opencode-plugin"
  },
  "homepage": "https://prismer.cloud",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "bin": {
    "prismer-codex": "./bin/prismer-codex"
  },
  "files": [
    "dist/",
    "bin/",
    "skills/",
    "scripts/",
    "README.md"
  ],
  "scripts": {
    "build": "tsup src/index.ts src/evolution-client.ts src/signals.ts src/resolve-config.ts --format esm --dts --out-dir dist",
    "prepublishOnly": "npm run build"
  },
  "devDependencies": {
    "tsup": "^8.0.0",
    "typescript": "^5.4.0",
    "vitest": "^3.2.4"
  },
  "engines": {
    "node": ">=18"
  },
  "publishConfig": {
    "access": "public"
  }
}
